import {canvas} from './renderer.js';
export function makeLandscapeDemo(){const c=canvas(1000,700),x=c.getContext('2d'),sky=x.createLinearGradient(0,0,0,520);sky.addColorStop(0,'#6a8cb2');sky.addColorStop(.53,'#a8bdc7');sky.addColorStop(.80,'#e9bd8d');sky.addColorStop(1,'#ecd09c');x.fillStyle=sky;x.fillRect(0,0,c.width,c.height);for(let i=0;i<8;i++){x.fillStyle=i%2?'#dfc8a464':'#c5d1d250';x.beginPath();x.ellipse(100+i*120,160+(i%3)*42,150,20,-.1,0,Math.PI*2);x.fill();}x.fillStyle='#566369';x.beginPath();x.moveTo(0,430);x.lineTo(190,310);x.lineTo(360,424);x.lineTo(540,350);x.lineTo(760,444);x.lineTo(1000,350);x.lineTo(1000,700);x.lineTo(0,700);x.fill();x.fillStyle='#2c4137';x.beginPath();x.moveTo(0,455);x.lineTo(200,415);x.lineTo(400,485);x.lineTo(650,425);x.lineTo(1000,447);x.lineTo(1000,700);x.lineTo(0,700);x.fill();x.fillStyle='#283b31';x.fillRect(0,510,1000,190);x.fillStyle='#42474a';x.beginPath();x.moveTo(520,475);x.bezierCurveTo(610,530,370,560,300,700);x.lineTo(710,700);x.bezierCurveTo(680,550,590,520,550,475);x.fill();for(let i=0;i<14;i++){const px=(i*179)%1000,py=430+(i%3)*40;x.fillStyle='#172c25';x.fillRect(px,py,7,118);x.beginPath();x.moveTo(px-32,py+68);x.lineTo(px+3,py-35);x.lineTo(px+39,py+68);x.fill();}x.fillStyle='#edf3e7';x.font='14px sans-serif';x.fillText('LUMA · MẪU ĐỒ HỌA PHONG CẢNH',28,31);x.font='12px sans-serif';x.fillText('Minh họa để thử công cụ · không phải ảnh chụp',28,676);return c;}
